package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.entity.*;import dev.kelmagic.resonance.*;import dev.kelmagic.research.*;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.*;import net.minecraft.client.gui.screens.inventory.InventoryScreen;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.*;import net.minecraft.world.InteractionHand;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;
@EventBusSubscriber(modid=KelMagic.MODID,value=Dist.CLIENT)
public final class QaResonance {
 static int stage,frame,wait;static boolean opened,requested;static volatile boolean ready,finished;static Preview preview;static CodexScreen bookScreen;
 static final String[] NAMES={"mage-front","mage-quarter","station-idle","station-ui","station-ritual-early","station-ritual-late","station-result","map-clean-edges","entry-first","entry-recipe","narrow-map","narrow-entry"};
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.resonanceQA118")||stage>12)return;var m=Minecraft.getInstance();if(stage==12){if(finished){stage=13;System.out.println("RESONANCE_NATIVE_118_COMPLETE");m.stop();}return;}if(m.level==null){if(!opened&&m.screen instanceof TitleScreen&&++wait>35){opened=true;m.createWorldOpenFlows().openWorld("KelMagicResearch118",()->{});}return;}if(m.player==null||m.getSingleplayerServer()==null)return;if(!requested){requested=true;ready=false;int at=stage;m.getSingleplayerServer().execute(()->{prepare(m.getSingleplayerServer().getPlayerList().getPlayers().getFirst(),at);ready=true;});return;}if(!ready)return;
 if(++frame==18){m.options.guiScale().set(stage>=10?3:2);if(stage==10)m.getWindow().setWindowed(960,720);m.resizeDisplay();m.getToasts().clear();m.options.hideGui=false;if(stage<2){if(preview==null)preview=new Preview(MagicCreatures.RED_MAGE.get().create(m.level));preview.view=stage;m.setScreen(preview);}else if(stage==2||stage>=4&&stage<=6){m.setScreen(null);m.options.hideGui=true;}else if(stage>=7){if(m.screen instanceof CodexScreen c)bookScreen=c;if(bookScreen==null)throw new IllegalStateException("expected codex");var c=bookScreen;c.selectSection(2);if(stage==8||stage==9||stage==11){m.setScreen(new ResearchEntryScreen(c,ResearchCatalog.BY_ID.get("golden_thread")));if(stage==9){var b=m.screen.children().stream().filter(v->v instanceof net.minecraft.client.gui.components.Button a&&a.getMessage().getString().equals("›")).map(v->(net.minecraft.client.gui.components.Button)v).findFirst().orElseThrow();b.onPress();}}}}
 if(frame==40){if((stage==8||stage==9||stage==11)&&!(m.screen instanceof ResearchEntryScreen))throw new IllegalStateException("entry was replaced");capture(m,NAMES[stage]);}if(stage==4&&frame>=20&&frame%4==0)capture(m,"ritual-frame-"+String.format("%03d",frame));if(stage==2&&frame==65)capture(m,"mana-pulse-later");int limit=stage==4?110:stage==2?75:55;if(frame>=limit){frame=0;requested=false;if(++stage==12)m.getSingleplayerServer().execute(()->{reset(m.getSingleplayerServer().getPlayerList().getPlayers().getFirst());finished=true;});}}
 static void prepare(ServerPlayer p,int at){var l=p.serverLevel();var pos=new BlockPos(44,-60,-8);if(at==0){p.setHealth(20);p.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.CREATIVE);p.connection.teleport(44,-60,-12,0,15);l.setDayTime(1000);l.setWeatherParameters(60000,0,false,false);l.setBlockAndUpdate(pos,MagicResonance.STATION.get().defaultBlockState());l.setBlockAndUpdate(new BlockPos(46,-60,-8),MagicResonance.MANA.get().defaultBlockState());l.setBlockAndUpdate(pos.west(),net.minecraft.world.level.block.Blocks.QUARTZ_BLOCK.defaultBlockState());for(var old:l.getEntitiesOfClass(RedMage.class,p.getBoundingBox().inflate(50)))old.discard();var mage=MagicCreatures.RED_MAGE.get().create(l);mage.setPos(41,-60,-8);mage.setNoAi(true);mage.setYRot(180);l.addFreshEntity(mage);var v=(ResonanceEntity)l.getBlockEntity(pos);v.inventory.setItem(0,Items.STRING.getDefaultInstance());v.inventory.setItem(1,Items.GOLD_NUGGET.getDefaultInstance());v.inventory.setItem(2,MagicContent.MANA_CORE.toStack());}
 if(at==2)p.connection.teleport(44.5,-60,-10.4,0,32);if(at==3){var v=(ResonanceEntity)l.getBlockEntity(pos);p.openMenu(v,b->b.writeBlockPos(pos));}
 if(at==4){p.closeContainer();p.getInventory().clearContent();var book=MagicArchive.CREATIVE_CODEX.toStack();p.getInventory().setItem(0,book);var s=Research.HYPOTHESIS.toStack();s.set(MagicComponents.RESEARCH_ID.get(),"golden_thread");s.set(MagicComponents.RESEARCH_OWNER.get(),p.getUUID().toString());p.getInventory().setItem(1,s);Research.save(p,ResearchState.EMPTY.add("tabs","materials").add("started","golden_thread").add("evidence","golden_thread:0").add("evidence","golden_thread:1"));dev.kelmagic.server.MagicServer.chat(new net.neoforged.neoforge.event.ServerChatEvent(p,"gut",Component.literal("gut")));if(!((ResonanceEntity)l.getBlockEntity(pos)).active())throw new IllegalStateException("chat trigger failed");}
 if(at==6){var v=(ResonanceEntity)l.getBlockEntity(pos);while(v.active())v.advance(p);if(!v.inventory.getItem(0).is(MagicMaterials.GOLDEN_THREAD))throw new IllegalStateException("ritual result mismatch");}
 if(at==7||at==10){p.setItemInHand(InteractionHand.MAIN_HAND,MagicArchive.CREATIVE_CODEX.toStack());Research.save(p,ResearchState.EMPTY.add("tabs","materials").add("learned","golden_thread"));MagicArchive.CREATIVE_CODEX.get().use(l,p,InteractionHand.MAIN_HAND);}
 }
 static void reset(ServerPlayer p){p.closeContainer();p.getInventory().clearContent();p.setData(dev.kelmagic.server.MagicAttachments.RESEARCH,ResearchState.EMPTY);var b=MagicArchive.CODEX.toStack();b.set(MagicComponents.CODEX_WORDS.get(),java.util.List.of("mina","no","pir","gut","lut","por","kor","puk","tik","kel","pul","vak","ged","rek","ped"));p.getInventory().setItem(0,b);int i=1;for(Item v:new Item[]{Items.PAPER,Items.STRING,Items.GOLD_INGOT,Items.IRON_INGOT,Items.LEATHER,Items.REDSTONE,Items.AMETHYST_SHARD,Items.GLASS,Items.STICK,Items.OAK_PLANKS,Items.GLASS_BOTTLE,Items.ENDER_PEARL,Items.BLAZE_ROD,Items.BLAZE_POWDER,Items.DIAMOND,Items.INK_SAC,Items.OAK_LOG,Items.COPPER_BLOCK,Items.IRON_BLOCK,Items.SMOOTH_STONE,Items.AMETHYST_BLOCK,Items.BOOK})p.getInventory().setItem(i++,new ItemStack(v,64));p.getInventory().setItem(i++,new ItemStack(MagicContent.MANA_CORE.get(),64));p.getInventory().setItem(i++,MagicCreatures.MAGE_EGG.toStack());p.getInventory().setItem(i++,MagicContent.SCRIPTER.toStack());p.getInventory().setItem(i++,MagicArchive.ANCIENT.toStack());var v=(ResonanceEntity)p.serverLevel().getBlockEntity(new BlockPos(44,-60,-8));if(v!=null)v.inventory.clearContent();p.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.SURVIVAL);p.setHealth(20);p.getAbilities().flying=false;p.onUpdateAbilities();p.connection.teleport(42,-60,-12,0,0);for(var mage:p.serverLevel().getEntitiesOfClass(RedMage.class,p.getBoundingBox().inflate(50)))mage.setNoAi(false);p.inventoryMenu.broadcastChanges();}
 static void capture(Minecraft m,String name){var dir=new java.io.File("/data/native-resonance-1.18");dir.mkdirs();Screenshot.grab(dir,name+".png",m.getMainRenderTarget(),v->{});System.out.println("RESONANCE_NATIVE_118_"+name);}
 static final class Preview extends Screen {final RedMage entity;int view;Preview(RedMage e){super(Component.literal("Рыжая чародейка"));entity=e;}public void render(GuiGraphics g,int mx,int my,float partial){g.fill(0,0,width,height,0xFF243238);g.fill(width/2-140,25,width/2+140,height-20,0xFF2C3D43);g.drawCenteredString(font,"Рыжая чародейка · 2,5 блока",width/2,12,0xFFE0CC9B);float angle=view==2?90:view==1?35:0;entity.yBodyRot=entity.yBodyRotO=180+angle;entity.setYRot(180+angle);entity.yHeadRot=entity.yHeadRotO=180+angle;entity.setXRot(0);float size=Math.min((height-75)/2.5f,140);InventoryScreen.renderEntityInInventory(g,width/2f,height/2f,size,new org.joml.Vector3f(0,entity.getBbHeight()/2+.03f,0),new org.joml.Quaternionf().rotationZ((float)Math.PI),new org.joml.Quaternionf(),entity);g.drawCenteredString(font,"Настоящая модель Minecraft",width/2,height-14,0xFFA9C4C1);}public boolean isPauseScreen(){return false;}}
}
